graphql.query:
query MyTrips($search: String) {
  myTrips(search: $search, orderBy: START_DATE, limit: 5) { id title status totalCost }
  myTripsCount(search: $search)
}

query Trip($id: ID!) {
  trip(id: $id) {
    title
    totalCost
    destinations { city countryCode activities { name category cost } }
    participants { role user { username email } }
  }
}

mutation Create($input: TripCreateInput!) {
  createTrip(input: $input) { trip { id title status owner { username } } }
}

mutation Update($id: ID!) {
  updateTrip(id: $id, input: {status: PLANNED}) { trip { status } }
}

mutation Create($input: DestinationCreateInput!) {
  createDestination(input: $input) { destination { id city countryCode } }
}

mutation Create($input: ActivityCreateInput!) {
  createActivity(input: $input) { activity { id name category cost } }
}

query Overview($id: ID!) {
  destinationOverview(id: $id) {
    destination { city }
    activityCount
    totalCost
    weather { timezone daily { date description } }
    country { name capital emoji }
    warnings { source code message }
  }
}

mutation Update($id: ID!) {
  updateTrip(id: $id, input: {title: "Piraté"}) { trip { id title } }
}

mutation Update($id: ID!, $end: Date!) {
  updateTrip(id: $id, input: {endDate: $end}) { trip { id } }
}

query Deep($id: ID!) {
  trip(id: $id) { destinations { trip { destinations { trip { destinations {
    trip { destinations { city } }
  } } } } } }
}
